    public int number = 0;
    public double area = 0.0d;
    public double fullWidth = 0.0d;
    public double botWidth = 0.0d;
    public double initSat = 0.0d;
    public double fromImperv = 0.0d;
    public double fromPerv = 0.0d;
    public int toPerv = 0;
    public int drainSubcatch = 0;
    public int drainNode = 0;
    public TLidRptFile rptFile = null;
    public TGrnAmpt soilInfil = new TGrnAmpt();
    public double surfaceDepth = 0.0d;
    public double paveDepth = 0.0d;
    public double soilMoisture = 0.0d;
    public double storageDepth = 0.0d;
    public double[] oldFluxRates = new double[4];
    public double dryTime = 0.0d;
    public double oldDrainFlow = 0.0d;
    public double newDrainFlow = 0.0d;
    public double volTreated = 0.0d;
    public double nextRegenDay = 0.0d;
    public TWaterBalance waterBalance = new TWaterBalance();
    TLidUnit copy() {
        TLidUnit c = new TLidUnit();
        c.@lidIndex = lidIndex;
        c.@number = number;
        c.@area = area;
        c.@fullWidth = fullWidth;
        c.@botWidth = botWidth;
        c.@initSat = initSat;
        c.@fromImperv = fromImperv;
        c.@fromPerv = fromPerv;
        c.@toPerv = toPerv;
        c.@drainSubcatch = drainSubcatch;
        c.@drainNode = drainNode;
        c.@rptFile = rptFile;
        c.@soilInfil = soilInfil.copy();
        c.@surfaceDepth = surfaceDepth;
        c.@paveDepth = paveDepth;
        c.@soilMoisture = soilMoisture;
        c.@storageDepth = storageDepth;
        c.@oldFluxRates = R.dup(oldFluxRates);
        c.@dryTime = dryTime;
        c.@oldDrainFlow = oldDrainFlow;
        c.@newDrainFlow = newDrainFlow;
        c.@volTreated = volTreated;
        c.@nextRegenDay = nextRegenDay;
        c.@waterBalance = waterBalance.copy();
        return c;
    }
}

@CompileStatic
final class TLidList {
    public TLidUnit lidUnit = null;
    public TLidList nextLidUnit = null;
    TLidList copy() {
        TLidList c = new TLidList();
        c.@lidUnit = lidUnit;
        c.@nextLidUnit = nextLidUnit;
        return c;
    }
}

