@CompileStatic
final class TUHGroup {
    public int isUsed = 0;
    public int rainInterval = 0;
    public double area = 0.0d;
    public double rdii = 0.0d;
    public double gageDate = 0.0d;
    public double lastDate = 0.0d;
    public TUHData[] uh = R.fill(new TUHData[3], (() -> new TUHData()));
    TUHGroup copy() {
        TUHGroup c = new TUHGroup();
        c.@isUsed = isUsed;
        c.@rainInterval = rainInterval;
        c.@area = area;
        c.@rdii = rdii;
        c.@gageDate = gageDate;
        c.@lastDate = lastDate;
        c.@uh = R.copyRecs(uh, new TUHData[uh.length]);
        return c;
    }
}

